import json, sys
import qiskit, rustworkx as rx
payload=json.load(sys.stdin)
rows=[]
for case in payload:
    namespace={}
    exec(case['code'],namespace)
    obj=namespace['create_and_modify_coupling_map']()
    detail={'physical_qubits':list(obj.physical_qubits),'edges':list(obj.get_edges())}
    try:
        exec(case['task']['upstream_test'],namespace)
        if case['suite']=='normal':
            namespace['check'](namespace['create_and_modify_coupling_map'])
        outcome='pass'
    except AssertionError as exc:
        outcome='fail'; detail['assertion']=str(exc)
    rows.append({'suite':case['suite'],'name':case['name'],'outcome':outcome,**detail})
graph=rx.PyDiGraph()
graph.add_nodes_from([None]*5)
for index in (3,1):graph.remove_node(index)
state=graph.__getstate__()
restored=rx.PyDiGraph();restored.__setstate__(state)
graph_probe={'serialized_state':state,'original_next_node':graph.add_node(None),
             'restored_next_node':restored.add_node(None)}
print(json.dumps({'qiskit':qiskit.__version__,'rustworkx':rx.__version__,
                  'cases':rows,'graph_probe':graph_probe}))
